import 'dart:convert';

import 'package:kafka_client/src/consumer_group_metadata.dart';
import 'package:test/test.dart';

List<int> hex(String value) {
  final compact = value.replaceAll(RegExp(r'\s'), '');
  return [
    for (var i = 0; i < compact.length; i += 2)
      int.parse(compact.substring(i, i + 2), radix: 16)
  ];
}

void main() {
  // Hand-derived, big-endian Kafka classic consumer-protocol fixtures. These
  // are not generated by the codec under test.
  final subscriptions = [
    hex('0000 00000002 0001 61 0002 ceb2 00000002 00ff'),
    hex('0001 00000002 0001 61 0002 ceb2 00000002 00ff '
        '00000001 0001 61 00000002 00000000 7fffffff'),
    hex('0002 00000002 0001 61 0002 ceb2 00000002 00ff '
        '00000001 0001 61 00000002 00000000 7fffffff 0000002a'),
    hex('0003 00000002 0001 61 0002 ceb2 00000002 00ff '
        '00000001 0001 61 00000002 00000000 7fffffff 0000002a '
        '0005 7261636b31'),
  ];
  final assignments = [
    for (var version = 0; version <= 3; version++)
      hex('000$version 00000002 0001 61 00000002 00000000 7fffffff '
          '0002 ceb2 00000000 00000002 00ff'),
  ];

  group('independent golden bytes', () {
    for (var version = 0; version <= 3; version++) {
      test('subscription version $version', () {
        final value = ConsumerGroupSubscription(['a', 'β'],
            version: version,
            userData: [0, 255],
            ownedPartitions: version >= 1
                ? {
                    'a': [0, 2147483647]
                  }
                : {},
            generationId: version >= 2 ? 42 : -1,
            rackId: version >= 3 ? 'rack1' : null);
        expect(value.toBytes(), subscriptions[version]);
        final decoded =
            ConsumerGroupSubscription.fromBytes(subscriptions[version]);
        expect(decoded.version, version);
        expect(decoded.topics, ['a', 'β']);
        expect(decoded.userData, [0, 255]);
        expect(decoded.ownedPartitions, value.ownedPartitions);
        expect(decoded.generationId, value.generationId);
        expect(decoded.rackId, value.rackId);
        expect(decoded.toBytes(), subscriptions[version]);
      });
      test('assignment version $version', () {
        final value = ConsumerGroupAssignment(
            {
              'a': [0, 2147483647],
              'β': []
            },
            version: version,
            userData: [0, 255]);
        expect(value.toBytes(), assignments[version]);
        final decoded = ConsumerGroupAssignment.fromBytes(assignments[version]);
        expect(decoded.version, version);
        expect(decoded.partitions, value.partitions);
        expect(decoded.userData, [0, 255]);
        expect(decoded.toBytes(), assignments[version]);
      });
    }
    test('null and empty bytes/rack remain distinct', () {
      final nullSub = hex('0003 00000000 ffffffff 00000000 ffffffff ffff');
      final emptySub = hex('0003 00000000 00000000 00000000 ffffffff 0000');
      expect(ConsumerGroupSubscription([], version: 3).toBytes(), nullSub);
      expect(
          ConsumerGroupSubscription([], version: 3, userData: [], rackId: '')
              .toBytes(),
          emptySub);
      expect(ConsumerGroupSubscription.fromBytes(nullSub).userData, isNull);
      expect(ConsumerGroupSubscription.fromBytes(nullSub).rackId, isNull);
      expect(ConsumerGroupSubscription.fromBytes(emptySub).userData, isEmpty);
      expect(ConsumerGroupSubscription.fromBytes(emptySub).rackId, '');
      expect(
          ConsumerGroupAssignment({}).toBytes(), hex('0000 00000000 ffffffff'));
      expect(ConsumerGroupAssignment({}, userData: []).toBytes(),
          hex('0000 00000000 00000000'));
      expect(
          ConsumerGroupAssignment.fromBytes(hex('0000 00000000 ffffffff'))
              .userData,
          isNull);
      expect(
          ConsumerGroupAssignment.fromBytes(hex('0000 00000000 00000000'))
              .userData,
          isEmpty);
    });
  });

  group('malformed wire', () {
    test('every truncation and trailing bytes at every version', () {
      for (final bytes in subscriptions) {
        for (var i = 0; i < bytes.length; i++) {
          expect(() => ConsumerGroupSubscription.fromBytes(bytes.sublist(0, i)),
              throwsFormatException,
              reason: 'subscription v${bytes[1]} prefix $i');
        }
        expect(() => ConsumerGroupSubscription.fromBytes([...bytes, 0]),
            throwsFormatException);
      }
      for (final bytes in assignments) {
        for (var i = 0; i < bytes.length; i++) {
          expect(() => ConsumerGroupAssignment.fromBytes(bytes.sublist(0, i)),
              throwsFormatException,
              reason: 'assignment v${bytes[1]} prefix $i');
        }
        expect(() => ConsumerGroupAssignment.fromBytes([...bytes, 0]),
            throwsFormatException);
      }
    });
    test('invalid version, input byte, arrays and nullable byte lengths', () {
      for (final parser in [
        ConsumerGroupSubscription.fromBytes,
        ConsumerGroupAssignment.fromBytes
      ]) {
        for (final wire in [
          hex('ffff 00000000 ffffffff'),
          hex('0004 00000000 ffffffff'),
          hex('7fff 00000000 ffffffff'),
          hex('0000 ffffffff ffffffff'),
          hex('0000 7fffffff ffffffff'),
          hex('0000 00000000 fffffffe'),
          hex('0000 00000000 7fffffff'),
          [-1, 0],
          [0, 256],
        ]) {
          expect(() => parser(wire), throwsFormatException, reason: '$wire');
        }
      }
    });
    test('invalid subscription strings and duplicates', () {
      for (final wire in [
        '0000 00000001 ffff ffffffff',
        '0000 00000001 fffe ffffffff',
        '0000 00000001 0000 ffffffff',
        '0000 00000001 0001 ff ffffffff',
        '0000 00000001 0002 c080 ffffffff',
        '0000 00000001 0003 eda080 ffffffff',
        '0000 00000002 0001 61 0001 61 ffffffff',
        '0003 00000000 ffffffff 00000000 ffffffff fffe',
        '0003 00000000 ffffffff 00000000 ffffffff 0001 ff',
      ]) {
        expect(() => ConsumerGroupSubscription.fromBytes(hex(wire)),
            throwsFormatException,
            reason: wire);
      }
    });
    test('invalid partition maps in assignment and subscription', () {
      for (final body in [
        'ffffffff',
        '7fffffff',
        '00000001 ffff 00000000',
        '00000001 0000 00000000',
        '00000001 0001 ff 00000000',
        '00000001 0001 61 ffffffff',
        '00000001 0001 61 7fffffff',
        '00000001 0001 61 00000001 ffffffff',
        '00000001 0001 61 00000001 80000000',
        '00000001 0001 61 00000002 00000001 00000001',
        '00000002 0001 61 00000000 0001 61 00000000',
      ]) {
        expect(
            () => ConsumerGroupAssignment.fromBytes(hex('0000 $body ffffffff')),
            throwsFormatException,
            reason: body);
        expect(
            () => ConsumerGroupSubscription.fromBytes(
                hex('0001 00000000 ffffffff $body')),
            throwsFormatException,
            reason: body);
      }
    });
  });

  group('construction and immutability', () {
    test('invalid fields and unsupported version fields fail', () {
      for (final version in [-1, 4, 32768]) {
        expect(() => ConsumerGroupSubscription([], version: version),
            throwsArgumentError);
        expect(() => ConsumerGroupAssignment({}, version: version),
            throwsArgumentError);
      }
      expect(() => ConsumerGroupSubscription([], ownedPartitions: {'a': []}),
          throwsArgumentError);
      expect(() => ConsumerGroupSubscription([], version: 1, generationId: 0),
          throwsArgumentError);
      expect(() => ConsumerGroupSubscription([], version: 2, rackId: ''),
          throwsArgumentError);
      for (final topic in [
        '',
        'a' * 32768,
        'β' * 16384,
        String.fromCharCode(0xd800),
        String.fromCharCode(0xdc00)
      ]) {
        expect(() => ConsumerGroupSubscription([topic]), throwsArgumentError);
        expect(() => ConsumerGroupAssignment({topic: []}), throwsArgumentError);
      }
      expect(() => ConsumerGroupSubscription(['a', 'a']), throwsArgumentError);
      for (final ids in [
        [-1],
        [2147483648],
        [0, 0]
      ]) {
        expect(() => ConsumerGroupAssignment({'a': ids}), throwsArgumentError);
        expect(
            () => ConsumerGroupSubscription([],
                version: 1, ownedPartitions: {'a': ids}),
            throwsArgumentError);
      }
      for (final bytes in [
        [-1],
        [256]
      ]) {
        expect(() => ConsumerGroupAssignment({}, userData: bytes),
            throwsArgumentError);
        expect(() => ConsumerGroupSubscription([], userData: bytes),
            throwsArgumentError);
      }
      for (final generation in [-2147483649, 2147483648]) {
        expect(
            () => ConsumerGroupSubscription([],
                version: 2, generationId: generation),
            throwsArgumentError);
      }
      expect(
          () => ConsumerGroupSubscription([], version: 3, rackId: 'β' * 16384),
          throwsArgumentError);
    });
    test('UTF-8 byte boundary and supplementary characters round-trip', () {
      for (final name in ['a' * 32767, 'β' * 16383, '😀']) {
        final value =
            ConsumerGroupSubscription([name], version: 3, rackId: name);
        final decoded = ConsumerGroupSubscription.fromBytes(value.toBytes());
        expect(decoded.topics, [name]);
        expect(decoded.rackId, name);
      }
      expect(utf8.encode('😀'), [0xf0, 0x9f, 0x98, 0x80]);
    });
    test('inputs, fields, decoded bytes and output are isolated', () {
      final topics = ['a'];
      final bytes = [1, 2];
      final ids = [0, 1];
      final partitions = {'a': ids};
      final sub = ConsumerGroupSubscription(topics,
          version: 1, userData: bytes, ownedPartitions: partitions);
      final assignment = ConsumerGroupAssignment(partitions, userData: bytes);
      final subWire = sub.toBytes().toList();
      final assignmentWire = assignment.toBytes().toList();
      topics.clear();
      bytes.clear();
      ids.clear();
      partitions.clear();
      expect(sub.toBytes(), subWire);
      expect(assignment.toBytes(), assignmentWire);
      expect(() => sub.topics.add('x'), throwsUnsupportedError);
      expect(() => sub.userData!.clear(), throwsUnsupportedError);
      expect(() => sub.ownedPartitions.clear(), throwsUnsupportedError);
      expect(() => sub.ownedPartitions['a']!.clear(), throwsUnsupportedError);
      expect(() => assignment.partitions.clear(), throwsUnsupportedError);
      expect(() => assignment.partitions['a']!.clear(), throwsUnsupportedError);
      expect(() => assignment.userData!.clear(), throwsUnsupportedError);
      final decoded = ConsumerGroupSubscription.fromBytes(subWire);
      final decodedAssignment =
          ConsumerGroupAssignment.fromBytes(assignmentWire);
      subWire.fillRange(0, subWire.length, 0);
      assignmentWire.fillRange(0, assignmentWire.length, 0);
      expect(decoded.userData, [1, 2]);
      expect(decodedAssignment.userData, [1, 2]);
      expect(
          () => decoded.ownedPartitions['a']!.clear(), throwsUnsupportedError);
      expect(() => decodedAssignment.partitions['a']!.clear(),
          throwsUnsupportedError);
      final returned = sub.toBytes();
      returned.fillRange(0, returned.length, 0);
      expect(sub.toBytes(), decoded.toBytes());
    });
  });
}
